#include "float_curve_sampler.h"
#include <iostream>
int main(){try{static_assert(sizeof(void*)==8,"x64 required");RecoveredFloatCurveSampler s;s.times={0,10000,30000,70000};s.values={0,1,3,7};s.info.defaultKind=0;s.minimum=-10;s.maximum=10;
 if(s.sample(20000)!=2||s.sample(70000)!=7||s.sample(80000)!=7||s.sample(10000)!=1)throw std::runtime_error("default sampler failed");
 s.info.defaultKind=0x606;if(s.sample(20000)!=2)throw std::runtime_error("linear sampler failed");s.info.defaultKind=0x404;if(s.sample(15000)!=1.3125f)throw std::runtime_error("smooth sampler failed");
 s.info.rightEdgeTime=80000;s.info.useEdgeInfo=true;s.info.rightActive=true;s.info.rightValue=9;if(s.sample(90000)!=9)throw std::runtime_error("right edge failed");
 if(recoveredCurveFraction(5,10,10)!=0||recoveredCurveFraction(5,10,0)!=0)throw std::runtime_error("nonascending fraction failed");
 s.info.rightEdgeTime=0;s.values={0,0,1,0};for(uint32_t code:{7u,8u,9u}){s.info.defaultKind=static_cast<int32_t>((code<<8)|code);auto result=s.sample(20000);auto p=recoveredParameterizedCurve(code);double a=(1.0+p.second)*(1.0+p.third)*(1.0-p.first),b=(1.0-p.second)*(1.0+p.third)*(1.0-p.first),c=(1.0+p.second)*(1.0-p.third)*(1.0-p.first),d=(1.0-p.second)*(1.0-p.third)*(1.0-p.first);double expected=.5+.0625*(d-c+.5*b);(void)a;if(std::abs(result-expected)>2e-6)throw std::runtime_error("parameterized sampling failed");}RecoveredFloatCurveSampler empty;empty.info.defaultKind=0x606;empty.info.rightEdgeTime=10000;empty.info.useEdgeInfo=true;empty.info.leftActive=true;empty.info.rightActive=true;empty.info.leftValue=2;empty.info.rightValue=6;empty.maximum=10;if(empty.sample(5000)!=4||empty.sample(15000)!=6||empty.sample(0)!=2)throw std::runtime_error("empty configured edges failed");empty.info.rightEdgeTime=0;bool emptyRejected=false;try{empty.sample(0);}catch(const std::runtime_error&){emptyRejected=true;}if(!emptyRejected)throw std::runtime_error("unsafe empty edge path guessed");
 s.info.defaultKind=0;float fallback=s.sample(20000);for(uint32_t code:{16u,17u,128u,255u}){s.info.defaultKind=static_cast<int32_t>((code<<8)|code);if(s.sample(20000)!=fallback)throw std::runtime_error("out of range fallback mismatch");}std::cout<<"curve_sampler_checks=10\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
